// Guardian Beast
// status: planned
// requires: static rule Prohibit BeAttachedBy
// requires: static rule Prohibit ChangeControl
// As long as this creature is untapped, noncreature artifacts you control can't be enchanted, they have indestructible, and other players can't gain control of them. This effect doesn't remove Auras already attached to those artifacts.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_0_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); (Some(asker.source).is_some_and(|candidate: ObjectId| !(q.state().obj(candidate).tapped))) && ((!((*so_far).is(CardType::Creature)) && (*so_far).is(CardType::Artifact) && Some(asker.controller) == Some(q.controller(affected)))) }
#[allow(unused_variables)] fn ability_0_0_0_rule(q: &dyn Query, asker: &Asker, id: ObjectId) -> bool { let source = asker.source; (Some(asker.source).is_some_and(|candidate: ObjectId| !(q.state().obj(candidate).tapped))) && (!(q.chars(id).is(CardType::Creature)) && q.chars(id).is(CardType::Artifact) && Some(asker.controller) == Some(q.controller(id))) }
#[allow(unused_variables)] fn ability_0_0_1_rule(q: &dyn Query, asker: &Asker, id: ObjectId) -> bool { let source = asker.source; (Some(asker.source).is_some_and(|candidate: ObjectId| !(q.state().obj(candidate).tapped))) && (!(q.chars(id).is(CardType::Creature)) && q.chars(id).is(CardType::Artifact) && Some(asker.controller) == Some(q.controller(id))) }
#[allow(unused_variables)] fn ability_0_1_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); (Some(asker.source).is_some_and(|candidate: ObjectId| !(q.state().obj(candidate).tapped))) && ((!((*so_far).is(CardType::Creature)) && (*so_far).is(CardType::Artifact) && Some(asker.controller) == Some(q.controller(affected)))) }
#[allow(unused_variables)] fn ability_0_1_apply_0(q: &dyn LayerQuery, source: ObjectId, chars: &mut Chars) { let asker = &Asker::new(source, q.controller(source)); chars.keywords = chars.keywords.with(Keyword::Indestructible); }
planned_item!("static-rule-prohibit-be-attached-by" => statics: object_rule(ability_0_0_0_rule, Rule::Cant(ObjectAction::BeAttachedBy { attachments: |q: &dyn Query, asker: &Asker, attachment: ObjectId| q.chars(attachment).has_subtype(q.words(asker.source).subtype(Subtype::Aura)), keep_existing: true })));
planned_item!("static-rule-prohibit-change-control" => statics: object_rule(ability_0_0_1_rule, Rule::Cant(ObjectAction::ChangeControl)));

